import{isNodePattern,throwError}from"@jimp/utils";export default()=>({gaussian(t,a){if("number"!=typeof t)return throwError.call(this,"r must be a number",a);if(t<1)return throwError.call(this,"r must be greater than 0",a);const i=Math.ceil(2.57*t),h=2*i+1,r=t*t*2,s=r*Math.PI,e=[];for(let t=0;t<h;t++){e[t]=[];for(let a=0;a<h;a++){const h=(a-i)**2+(t-i)**2;e[t][a]=Math.exp(-h/r)/s}}for(let t=0;t<this.bitmap.height;t++)for(let a=0;a<this.bitmap.width;a++){let r=0,s=0,o=0,m=0,n=0;for(let d=0;d<h;d++){for(let p=0;p<h;p++){const h=Math.min(this.bitmap.width-1,Math.max(0,p+a-i)),b=Math.min(this.bitmap.height-1,Math.max(0,d+t-i)),l=e[d][p],u=b*this.bitmap.width+h<<2;r+=this.bitmap.data[u]*l,s+=this.bitmap.data[u+1]*l,o+=this.bitmap.data[u+2]*l,m+=this.bitmap.data[u+3]*l,n+=l}const p=t*this.bitmap.width+a<<2;this.bitmap.data[p]=Math.round(r/n),this.bitmap.data[p+1]=Math.round(s/n),this.bitmap.data[p+2]=Math.round(o/n),this.bitmap.data[p+3]=Math.round(m/n)}}return isNodePattern(a)&&a.call(this,null,this),this}});